function planRoadPanel(id,key){if(g.provinceBoard&&g.cities[id].owner!==0){claimOrContact(id);return;}if(g.cities[id].owner===null){claimPanel(id);return;}const c=g.cities[id],road=planFor(id).roads.find(r=>r.key===key);if(!road)return;const pending=g.projects.find(p=>p.city===id&&p.type==='planRoad'&&p.roadKey===key),opened=c.streets.some(r=>r.planRoad===key),box=panelBox(road.name,'planRoad',{id,key,signature:[pending?.id,opened,c.streets.length].join('|')});text(box,COMUNI[id].name+' · tracciato predefinito');if(opened){text(box,'Strada aperta. Le aree servite possono essere acquistate e potenziate.');if(g.cities.filter(c=>c.owner===0).length>1)box.append(btn('Collegamenti fra comuni',()=>unifyPanel(id)));return;}if(pending){const status=text(box,'Cantiere · '+Math.ceil(pending.remaining)+'s');status.dataset.siteProgress='true';return;}const q=quotePlanRoad(g,0,id,key);text(box,q.reason||num(q.cost)+' € · '+q.materials+' merci · '+q.duration+'s');if(!q.reason){const buy=btn('Apri il cantiere',()=>{if(command({type:'openRoad',city:id,roadKey:key}))planRoadPanel(id,key);},'primary');buy.dataset.planPurchase='road';buy.disabled=g.players[0].cash<q.cost||g.players[0].goods<q.materials;box.append(buy);}}
function updatePlanPanels(){if(panel?.kind==='site'){const d=panel.data,c=g.cities[d.id],site=c.plan.sites.find(s=>s.id===d.siteId),state=siteState(g,c,site),road=neededRoad(c,site.road),roadProject=g.projects.find(p=>p.city===d.id&&p.type==='planRoad'&&p.roadKey===road?.key),signature=[state.building?.id,state.project?.id,state.roadOpen,roadProject?.id].join('|');if(signature!==d.signature){sitePanel(d.id,d.siteId);return;}const progress=$('panelBody').querySelector('[data-site-progress]');if(progress)progress.textContent='Cantiere · '+Math.ceil((state.project||roadProject)?.remaining||0)+'s';const buy=$('panelBody').querySelector('[data-plan-purchase]'),q=state.roadOpen?quoteBuild(g,0,d.id,site.type,null,site.id):road?quotePlanRoad(g,0,d.id,road.key):{reason:'Indisponibile'};if(buy)buy.disabled=!!q.reason||g.players[0].cash<q.cost||g.players[0].goods<q.materials;const status=$('panelBody').querySelector('[data-plan-status]');if(status)status.textContent=q.reason||(g.players[0].goods<q.materials?'Merci insufficienti: attendi la produzione o acquista risorse.':'Area pronta per il cantiere.');}if(panel?.kind==='planRoad'){const d=panel.data,c=g.cities[d.id],pending=g.projects.find(p=>p.city===d.id&&p.type==='planRoad'&&p.roadKey===d.key),signature=[pending?.id,c.streets.some(r=>r.planRoad===d.key),c.streets.length].join('|');if(signature!==d.signature){planRoadPanel(d.id,d.key);return;}const progress=$('panelBody').querySelector('[data-site-progress]');if(progress)progress.textContent='Cantiere · '+Math.ceil(pending?.remaining||0)+'s';const q=quotePlanRoad(g,0,d.id,d.key),buy=$('panelBody').querySelector('[data-plan-purchase]');if(buy)buy.disabled=!!q.reason||g.players[0].cash<q.cost||g.players[0].goods<q.materials;}}
function claimPanel(id){if(g.provinceBoard){const from=COMUNI[id].neighbors.find(n=>g.cities[n].owner===0);if(from!==undefined){frontierPanel(from,id);return;}}const q=expansionQuote(g,0,id),box=panelBox('Una sede a '+COMUNI[id].name,'claim',{id});if(q.reason){text(box,q.reason);return;}const profile=municipalProfile(id);text(box,profile.title+' · '+profile.summary);text(box,q.remote?'Sede distaccata: investimento più alto. Non crea una strada attraverso comuni altrui.':'Concessione confinante: comprende il collegamento con '+COMUNI[q.source].name+'.');const price=document.createElement('div');price.className='price';price.textContent=num(q.cost)+' €';box.append(price);const materialNote=text(box,'Materiali: '+q.materials+' merci. Il costo di nuove sedi cresce con la rete.');materialNote.dataset.claimMaterials='true';text(box,q.duration+'s per aprire. La sede entra al 65% di stabilità e cresce gradualmente fino al pieno rendimento.');const b=btn('Apri la sede',()=>{if(command({type:'claim',city:id}))toast('Concessione in preparazione. Puoi tornare nella provincia.');},'primary');b.dataset.claimPurchase='true';b.disabled=g.players[0].cash<q.cost||g.players[0].goods<q.materials;box.append(b);}
function metric(box,label,value){const row=document.createElement('div');row.className='metric';const l=document.createElement('span'),v=document.createElement('b');l.textContent=label;v.textContent=value;row.append(l,v);box.append(row);}
function localEconomy(id){const c=g.cities[id],r=economy(g).cities[id],owner=c.owner,box=panelBox('Bilancio · '+COMUNI[id].name,'economy',{id});metric(box,'Entrate correnti',num(r.income)+' €/min');metric(box,'Popolazione',num(c.population));metric(box,'Saldo migratorio',(r.netMigration>=0?'+':'')+num(r.netMigration)+'/min');metric(box,'Stabilità',Math.round(c.stability*100)+'%');if(owner!==null){metric(box,'Energia / deposito',num(g.players[owner].energy)+' / '+num(economy(g).players[owner].storage));metric(box,'Merci / deposito',num(g.players[owner].goods)+' / '+num(economy(g).players[owner].storage));}const history=c.history,max=Math.max(...history)+1,min=Math.min(...history)-1,poly=history.map((v,i)=>`${i/Math.max(1,history.length-1)*250},${60-(v-min)/(max-min)*50}`).join(' ');const div=document.createElement('div');div.innerHTML='<svg class="trend" viewBox="0 0 250 70" role="img" aria-label="Andamento della popolazione"><polyline points="'+poly+'"/></svg>';box.append(div);text(box,'Valori di simulazione, non dati demografici reali. La qualità locale attira residenti dalle altre reti; nessun comune scende sotto il minimo.');}
function goodsPanel(){const q=goodsBalance(g,0),box=panelBox('Merci della società','goods');metric(box,'Produzione industriale','+'+q.production.toLocaleString('it-IT',{maximumFractionDigits:1})+'/min');metric(box,'Consumo del commercio','−'+q.consumption.toLocaleString('it-IT',{maximumFractionDigits:1})+'/min');metric(box,'Saldo netto',(q.net>=0?'+':'')+q.net.toLocaleString('it-IT',{maximumFractionDigits:1})+'/min');metric(box,'Deposito condiviso',num(q.stock)+' / '+num(q.storage));const notes=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Come si producono e si usano';notes.append(summary);box.append(notes);text(notes,'Ogni livello di industria produce 24 merci/min con energia sufficiente. Ogni livello di commercio ne usa 6/min e genera denaro. I valori sono minuti di gioco: ×2 e ×5 accelerano anche la produzione.');text(notes,'Costruzioni, potenziamenti, strade e nuove sedi spendono merci. La logistica aggiunge 100 posti per livello al deposito iniziale di 500. Con il deposito pieno la produzione in eccesso non viene conservata.');text(notes,q.energyEfficiency<1?'Poca energia: le industrie stanno lavorando al '+Math.round(q.energyEfficiency*100)+'%. Costruisci o potenzia Energia.':'Energia sufficiente: le industrie lavorano al 100%.');text(notes,'La riserva è comune a tutti i tuoi comuni. Puoi anche comprare o vendere merci tramite accordi. Economia cooperativa: produzione industriale +15%.');}
function neighborsPanel(id,next=COMUNI[id].neighbors[0]){const box=panelBox('Comuni confinanti','roads',{id,next});if(next===undefined){text(box,'Exclave: nessun comune milanese direttamente confinante. Puoi aprire una sede distaccata nella provincia.');return;}const label=document.createElement('label');label.textContent='SCEGLI IL VICINO';const select=document.createElement('select');select.id='roadNeighbor';for(const n of COMUNI[id].neighbors){const o=document.createElement('option');o.value=n;o.textContent=COMUNI[n].name;select.append(o);}select.value=next;select.onchange=()=>neighborsPanel(id,+select.value);label.append(select);box.append(label);const c=g.cities[next],owner=c.owner,q=roadQuote(g,0,id,next);text(box,owner===null?'Comune libero':g.players[owner].name);if(owner===null)box.append(btn('Valuta una nuova sede',()=>{enter(next);claimPanel(next);},'primary'));else if(g.cities[id].owner===0){if(q.reason)text(box,q.reason);else if(q.permission)box.append(btn('Chiedi il passaggio',()=>offerPanel(owner,'transit',{city:next,a:id}),'primary'));else{const build=btn('Collega · '+num(q.cost)+' €',()=>{if(command({type:'road',a:id,b:next}))neighborsPanel(id,next);},'primary');build.disabled=g.players[0].cash<q.cost;box.append(build);}}box.append(btn('Entra nel comune',()=>enter(next)));text(box,'Le strade collegano solo comuni confinanti. Per quelli altrui serve consenso; la coalizione concede passaggio reciproco finché è attiva.');}

const labels={buy:'Compra risorse',sell:'Vendi risorse',transit:'Permesso stradale',coalition:'Coalizione',acquisition:'Acquista il comune'};
