function dialog(title){const box=$('dialogBody');box.replaceChildren();const h=document.createElement('h2');h.textContent=title;box.append(h);if(!$('dialog').open)$('dialog').showModal();return box;}
function help(){const was=paused;paused=true;const box=dialog('Comuni & Capitali');text(box,'Scegli un comune e apri la tua società. La provincia è una sola mappa continua. Le strade esistono già e tutti i comuni hanno quartieri predefiniti: tocca le aree per acquistare e costruire. Tocca un accesso + sul confine e scegli Unifica ed espandi, senza cambiare vista. Non occorre posizionare edifici.');text(box,'Industria ed energia producono risorse. Commercio e quartieri trasformano gli investimenti in entrate e attrattiva. Se mancano merci o energia, il rendimento si riduce. Scambia risorse con le altre società.');text(box,'I collegamenti richiedono comuni confinanti: per attraversare quelli altrui serve consenso o una coalizione. Le sedi distaccate costano di più e non creano strade automatiche. Ogni accordo viene accettato o rifiutato.');text(box,'La partita continua: nessun timer e nessun vincitore finale. Il primato combina rendite (50%), sviluppo (35%) e liquidità (15%), in rapporto agli altri. I cantieri usano denaro e merci; la logistica amplia i depositi. Ogni comune offre un numero diverso di aree industriali e commerciali. Le concessioni aeroportuali sono rare. Scegli dove espanderti in base alle opportunità disponibili. Posizioni e collegamenti sono fissi; i potenziamenti sviluppano le aree già acquistate. Le filosofie hanno modificatori di gioco.');box.append(btn('Ho capito',()=>{$('dialog').close();paused=was;},'primary'));}
function menu(){paused=true;update();const box=dialog('La tua società');box.append(btn('Riprendi',()=>{$('dialog').close();paused=false;},'primary'),btn('Salva e torna all’ingresso',()=>{$('dialog').close();toHome();}),btn('Come si gioca',help));}

$('buildingUpgrade').onclick=()=>{if(panel?.kind==='frontier'){const {from,to}=panel.data;if(command({type:'expand',from,city:to},{keep:true}))frontierPanel(from,to);return;}if(panel?.kind==='site'){const {id,siteId}=panel.data,site=planFor(id).sites.find(s=>s.id===siteId);if(command({type:'build',city:id,sector:site.type,site:siteId},{keep:true}))sitePanel(id,siteId);return;}if(panel?.kind!=='building')return;const {id,buildingId}=panel.data,b=g.cities[id].buildings.find(b=>b.id===buildingId);if(command({type:'build',city:id,sector:b.type,buildingId,point:b.point},{keep:true}))inspectBuilding(id,buildingId);};$('companiesBtn').onclick=()=>{close();portfolio.open();};$('rivalsBtn').onclick=()=>{close();relations.open();};$('zoomRange').oninput=e=>{view.stopCamera();view.setZoom(zoomFromSlider(e.target.value));update();};$('overview').onclick=province;$('unifyBtn').onclick=()=>unifyPanel();$('start').onclick=start;$('resume').onclick=()=>{const s=saved();if(s)activate(s);};$('resume').hidden=!saved();$('placementBack').onclick=toHome;$('province').onclick=$('backProvince').onclick=province;$('rankToggle').onclick=()=>{rankOpen=!rankOpen;update();};$('closePanel').onclick=()=>{mode=null;streetStart=null;close();toolbar();};$('inbox').onclick=inbox;$('goodsCard').onclick=goodsPanel;$('goodsCard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();goodsPanel();}};$('economyBtn').onclick=()=>localEconomy(view.local);$('roadsBtn').onclick=()=>neighborsPanel(view.local);$('claimBtn').onclick=()=>claimPanel(view.local);$('contactBtn').onclick=()=>showCompany(g.cities[view.local].owner);$('homeHelp').onclick=$('help').onclick=help;$('pause').onclick=()=>{paused=!paused;update();};$('speed').onclick=()=>{speed=speed===1?2:speed===2?5:1;update();};$('zoomIn').onclick=()=>view.setZoom(view.zoom*1.75);$('zoomOut').onclick=()=>view.setZoom(view.zoom/1.75);$('center').onclick=()=>{view.stopCamera();if(view.local!==null)view.setLocal(view.local);else view.overview();update();};$('menu').onclick=menu;
document.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;if(e.key==='Escape'){mode=null;streetStart=null;close();toolbar();}if(e.key===' '&&!home){e.preventDefault();paused=!paused;update();}});document.addEventListener('pointerdown',e=>{if(!e.target.closest('#panel,#buildingUpgrade,#investments,#localStats,#ranking,#inbox,#portfolio,#relations,#mapTools,#zoomRange')&&e.target.id!=='map')close();});$('dialog').addEventListener('cancel',()=>{if(g.phase==='playing'&&!home)paused=false;});$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){$('dialog').close();if(!home&&g.phase==='playing')paused=false;}});document.addEventListener('visibilitychange',()=>{if(document.hidden){save();if(!home){paused=true;update();}}});window.addEventListener('pagehide',save);doctrines();
function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(!home&&!paused&&g.phase==='playing')advance(g,dt*speed);if(now-lastUI>300){update();lastUI=now;}if(now-lastSave>10000){save();lastSave=now;}view.tickCamera(dt);view.draw();positionBuildingAction();requestAnimationFrame(frame);}requestAnimationFrame(frame);

function streetPanel(id,a,b,toCity=id){if(toCity!==id){const q=quoteUnify(g,0,id,toCity,'extraurban',a,b),box=panelBox('Collegamento tra comuni','crossStreet',{id,toCity,a,b});view.linkPreview=q.reason?null:q;view.roadPreview=null;text(box,q.reason||COMUNI[id].name+' ↔ '+COMUNI[toCity].name+' · '+q.materials+' merci');if(!q.reason){text(box,num(q.cost)+' € · '+q.length.toFixed(1)+' km');const buy=btn('Collega e unifica',()=>{if(command({type:'unify',a:id,b:toCity,kind:'extraurban',from:a,to:b})){streetStart=null;mode=null;toolbar();}},'primary');buy.disabled=g.players[0].cash<q.cost||g.players[0].goods<q.materials;box.append(buy);}box.append(btn('Riprova',()=>{streetStart=null;close();}));return;}const q=quoteStreet(g,0,id,a,b),box=panelBox('Nuova strada locale','street',{id,a,b});view.roadPreview=q;if(q.reason){text(box,q.reason);box.append(btn('Riprova',()=>{streetStart=null;close();}));return;}const price=document.createElement('div');price.className='price';price.textContent=num(q.cost)+' €';box.append(price);text(box,q.materials+' merci · tracciato sulla griglia. Per unire due comuni, tocca una strada in ciascuno.');const buy=btn('Costruisci strada',()=>{if(command({type:'street',city:id,a,b})){streetStart=null;mode=null;toolbar();}},'primary');buy.dataset.streetPurchase='true';buy.disabled=g.players[0].cash<q.cost||g.players[0].goods<q.materials;box.append(buy,btn('Annulla',()=>{streetStart=null;close();mode=null;toolbar();}));}

function pickBoard(id,hit){
 if(hit?.kind==='company'){showCompany(hit.owner);return;}
 if(view.transform().scale<22){close();view.setLocal(id);toolbar();update();return;}
 if(hit?.kind==='frontier'){frontierPanel(hit.from,hit.to);return;}
 view.selectTown(hit?.city??id);mode=null;toolbar();update();
 if(hit?.kind==='site'){if(g.cities[hit.city].owner===0)sitePanel(hit.city,hit.id);else claimOrContact(hit.city);return;}
 if(hit?.kind==='building'){if(g.cities[id].owner===0)inspectBuilding(id,hit.id);else showCompany(g.cities[id].owner);return;}
 if(hit?.kind==='street'||hit?.kind==='planRoad'){if(g.cities[id].owner===0)planRoadPanel(id,hit.roadKey||hit.id);else claimOrContact(id);return;}
 if(hit?.kind==='link'){const l=g.urbanLinks.find(l=>l.id===hit.id);if(l&&l.owner===0)unifyPanel(l.a,l.b,l.kind);return;}
 if(g.cities[id].owner!==0){claimOrContact(id);return;}close();
}
function claimOrContact(id){const from=COMUNI[id].neighbors.find(n=>g.cities[n].owner===0);if(from!==undefined)frontierPanel(from,id);else if(g.cities[id].owner===null)claimPanel(id);else showCompany(g.cities[id].owner);}
function frontierPanel(from,to){
 const c=g.cities[to],pending=g.projects.find(p=>p.type==='claim'&&p.city===to),box=panelBox(COMUNI[from].name+' ↔ '+COMUNI[to].name,'frontier',{from,to,pending:pending?.id||null,owner:c.owner});
 if(g.provinceBoard&&c.owner===null)$('panel').hidden=true;text(box,'Accesso sulla rete esistente · nessun cambio di mappa');
 if(c.owner===0){text(box,'I due comuni fanno parte del tuo territorio.');box.append(btn('Migliora i collegamenti',()=>unifyPanel(from,to),'primary'));return;}
 if(c.owner!==null){text(box,'Concessione di '+g.players[c.owner].name+'. L’unificazione richiede il consenso del proprietario.');box.append(btn('Proponi acquisto',()=>offerPanel(c.owner,'acquisition',{city:to}),'primary'));return;}
 const profile=municipalProfile(to);text(box,profile.title);text(box,Object.entries(profile.counts).filter(([,n])=>n).map(([t,n])=>n+' '+ZONE_NAMES[t].toLowerCase()).join(' · '));
 if(pending){const note=text(box,'Concessione in preparazione · '+Math.ceil(pending.remaining)+'s');note.dataset.frontierProgress='true';return;}
 const q=expansionQuote(g,0,to);if(q.reason){text(box,q.reason);return;}const price=document.createElement('div');price.className='price';price.textContent=num(q.cost)+' €';box.append(price);text(box,q.materials+' merci · '+q.duration+'s · collegamento incluso');
 const buy=btn('Unifica ed espandi',()=>{if(command({type:'expand',from,city:to})){frontierPanel(from,to);toast('Espansione avviata. Continua a sviluppare i tuoi quartieri.');}},'primary');buy.dataset.frontierPurchase='true';buy.disabled=g.players[0].cash<q.cost||g.players[0].goods<q.materials;if(!g.provinceBoard)box.append(buy);positionFrontierAction();
}
function updateFrontier(){if(panel?.kind!=='frontier')return;const d=panel.data,c=g.cities[d.to],pending=g.projects.find(p=>p.type==='claim'&&p.city===d.to);if(c.owner===0&&d.owner!==0){close();return;}if(c.owner!==d.owner||(pending?.id||null)!==d.pending){frontierPanel(d.from,d.to);return;}const progress=$('panelBody').querySelector('[data-frontier-progress]');if(progress)progress.textContent='Concessione in preparazione · '+Math.ceil(pending.remaining)+'s';const buy=$('panelBody').querySelector('[data-frontier-purchase]');if(buy){const q=expansionQuote(g,0,d.to);buy.disabled=!!q.reason||g.players[0].cash<q.cost||g.players[0].goods<q.materials;}}

function positionSiteAction(){const action=$('buildingUpgrade'),d=panel.data,c=g.cities[d.id],site=planFor(d.id).sites.find(s=>s.id===d.siteId);if(home||!site||c.owner!==0||view.transform().scale<22){action.hidden=true;return;}const state=siteState(g,c,site),[x,y]=view.screen(site.point),height=site.lot.h*site.lot.step*view.transform().scale/2;action.hidden=x<0||x>view.w||y<80||y>view.h-80;if(action.hidden)return;const key=g.step+':'+g.projects.length;if(d.quoteKey!==key){d.quoteKey=key;d.quote=quoteBuild(g,0,d.id,site.type,null,site.id);}const q=d.quote;action.style.left=Math.max(85,Math.min(view.w-85,x))+'px';action.style.top=Math.max(view.w<600?190:105,y-height-9)+'px';const label=state.project?'◷ Cantiere · '+Math.ceil(state.project.remaining)+'s':q.reason||'Acquista · '+num(q.cost)+' €';if(action.textContent!==label)action.textContent=label;action.disabled=!!state.project||!!q.reason||g.players[0].cash<q.cost||g.players[0].goods<q.materials;action.setAttribute('aria-label','Acquista area '+SECTORS[site.type].name);}

function positionFrontierAction(){const action=$('buildingUpgrade');if(panel?.kind!=='frontier'||home){action.hidden=true;return;}const {from,to}=panel.data,c=g.cities[to],road=publicRoad(g,from,to);if(!road||c.owner!==null||view.transform().scale<22){action.hidden=true;return;}const pending=g.projects.find(p=>p.type==='claim'&&p.city===to),key=g.step+':'+g.projects.length;if(panel.data.quoteKey!==key){panel.data.quoteKey=key;panel.data.quote=expansionQuote(g,0,to);}const q=panel.data.quote,[x,y]=view.screen(road.gate);action.hidden=x<0||x>view.w||y<80||y>view.h-65;if(action.hidden)return;action.style.left=Math.max(90,Math.min(view.w-90,x))+'px';action.style.top=Math.max(view.w<600?190:105,y-24)+'px';const label=pending?'◷ Espansione · '+Math.ceil(pending.remaining)+'s':'Espandi · '+num(q.cost)+' €';if(action.textContent!==label)action.textContent=label;action.disabled=!!pending||!!q.reason||g.players[0].cash<q.cost||g.players[0].goods<q.materials;action.setAttribute('aria-label','Espandi in '+COMUNI[to].name);action.setAttribute('aria-describedby','mapActionInfo');const info=$('mapActionInfo');info.hidden=false;info.style.left=action.style.left;info.style.top=(parseFloat(action.style.top)+5)+'px';const detail=COMUNI[to].name+' · '+(pending?'in preparazione':q.materials+' merci · '+q.duration+'s');if(info.textContent!==detail)info.textContent=detail;}


function locateAsset(city,buildingId,siteId){
 close();view.setLocal(city);const building=g.cities[city].buildings.find(b=>b.id===buildingId),site=siteId?planFor(city).sites.find(s=>s.id===siteId):null;if(building||site)view.focusPoint((building||site).point);toolbar();update();if(building)inspectBuilding(city,building.id);else if(site)sitePanel(city,site.id);
}
function locateCompany(owner){
 const homeId=g.players[owner].home,id=g.cities[homeId]?.owner===owner?homeId:g.cities.find(c=>c.owner===owner)?.id;if(id===null||id===undefined)return;close();view.focusOwner=owner;view.setLocal(id);toolbar();update();showCompany(owner);
}
function proposeAlliance(to){
 if(relationship(g,to)==='ally'){toast('Questa società è già tua alleata.');return;}
 const pending=pendingAlliance(g,to);if(pending){close();inbox();return;}
 if(command({type:'offer',to,kind:'coalition',fee:0,quantity:0})){toast('Proposta inviata: attendo il consenso della società.');relations.open();}
}
function showCompany(owner){
 close();view.focusOwner=owner;
 if(owner===0){portfolio.open();return;}
 const row=standings(g).find(r=>r.id===owner),rel=relationship(g,owner),box=panelBox(g.players[owner].name,'company',{owner});
 const badge=document.createElement('span');badge.className='relationBadge '+rel;badge.textContent=rel==='ally'?'↔ Alleato':rel==='trade'?'Passaggio autorizzato':'Società concorrente';box.append(badge);
 metric(box,'Liquidità',num(row.cash)+' €');metric(box,'Entrate','+'+num(row.income)+' €/min');metric(box,'Territorio',row.cities+' comuni');
 box.append(btn('⌖ Mostra sulla mappa',()=>locateCompany(owner)),btn('Scambia risorse',()=>offerPanel(owner,'buy')));
 if(rel==='ally')text(box,'Passaggio reciproco e +5% entrate. Le casse restano separate.');else box.append(btn(pendingAlliance(g,owner)?'Apri proposta':'Proponi alleanza · +5%',()=>proposeAlliance(owner),'primary'));
 const target=g.cities[view.local]?.owner===owner?view.local:g.cities[g.players[owner].home]?.owner===owner?g.players[owner].home:g.cities.find(c=>c.owner===owner)?.id;if(target!==undefined&&target!==null){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Acquisto di un comune';details.append(summary,btn('Proponi acquisto · '+COMUNI[target].name,()=>offerPanel(owner,'acquisition',{city:target})));box.append(details);}
}

function refreshCompanyPanel(e){
 if(panel?.kind!=='company')return;const owner=panel.data.owner,p=g.players[owner],r=e.players[owner],rows=$('panelBody').querySelectorAll('.metric b');if(rows.length<3)return;
 rows[0].textContent=num(p.cash)+' €';rows[1].textContent='+'+num(r.income)+' €/min';rows[2].textContent=r.cities+' comuni';
 const badge=$('panelBody').querySelector('.relationBadge'),rel=relationship(g,owner);if(badge){badge.className='relationBadge '+rel;badge.textContent=rel==='ally'?'↔ Alleato':rel==='trade'?'Passaggio autorizzato':'Società concorrente';}
}
